"""Influence-map threat diffusion and tower placement."""

MAP = [
    "--3--",
    "-----",
    "2---4",
    "-----",
    "--1--",
]


def parse_map(grid):
    """Return (intensity dict {(r,c): v}, buildable set {(r,c)}, shape)."""
    spawns = {}
    buildable = set()
    for r, row in enumerate(grid):
        for c, ch in enumerate(row):
            if ch.isdigit():
                spawns[(r, c)] = float(ch)
            elif ch == "-":
                buildable.add((r, c))
    return spawns, buildable, (len(grid), len(grid[0]))


def threat_field(spawns, shape):
    """threat[r][c] = sum over spawns of intensity / (1 + manhattan_distance)."""
    rows, cols = shape
    field = [[0.0] * cols for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            total = 0.0
            for (sr, sc), intensity in spawns.items():
                d = abs(sr - r) + abs(sc - c)
                total += intensity / (1 + d)
            field[r][c] = total
    return field


def covered_threat(field, r, c):
    """Total threat in the Chebyshev-radius-1 neighborhood of (r,c), clipped."""
    rows, cols = len(field), len(field[0])
    total = 0.0
    for dr in (-1, 0, 1):
        for dc in (-1, 0, 1):
            rr, cc = r + dr, c + dc
            if 0 <= rr < rows and 0 <= cc < cols:
                total += field[rr][cc]
    return total


def best_placement(grid=MAP):
    """Row-major-first best (score, (r, c)) over all buildable cells."""
    spawns, buildable, shape = parse_map(grid)
    field = threat_field(spawns, shape)
    best_cell, best_score = None, None
    # iterate row-major so ties keep the earliest cell
    for r in range(shape[0]):
        for c in range(shape[1]):
            if (r, c) not in buildable:
                continue
            s = covered_threat(field, r, c)
            if best_score is None or s > best_score:
                best_score, best_cell = s, (r, c)
    return best_cell, best_score


def brute_force_best(grid=MAP):
    """Independent reference: max score over buildable cells, row-major ties."""
    spawns, buildable, shape = parse_map(grid)
    field = threat_field(spawns, shape)
    scored = sorted(
        ((covered_threat(field, r, c), (r, c)) for (r, c) in buildable),
        key=lambda t: (-t[0], t[1]),
    )
    return scored[0][1], scored[0][0]

